private static function handover_post_readback( $s, $plan ) {
	self::handover_post_fresh( $s['delivery'] );
	if ( self::handover_post_snapshot( $s['delivery'] ) !== $s || ! self::handover_post_journal_matches( get_post_meta( $s['delivery'], '_tkd_fo_delivery_stock_journal', true ), $plan['journal'] ) || ! get_post_meta( $s['delivery'], '_tkd_fo_delivery_stock_processed_at', true ) || get_post_meta( $s['order'], '_tkd_fo_stock_error', true ) ) { return false; }
