	foreach ( $after as $key => $qty ) { if ( ! isset( $plan['reservation_before'][$key] ) || $qty > $plan['reservation_before'][$key] || $qty < 0 ) { return false; } }
	$ship = array(); foreach ( $plan['journal'] as $entry ) { $ship[$entry['item_id']] = $entry['quantity']; }
	foreach ( $plan['stock_before'] as $key => $before ) {
		$item = TKD_FO_DB::get_item( $key ); $released = ( $plan['reservation_before'][$key] ?? 0 ) - ( $after[$key] ?? 0 );
		if ( ! $item || round( (float) $item->on_hand, 3 ) !== round( $before['on_hand'] - ( $ship[$key] ?? 0 ), 3 ) || round( (float) $item->reserved, 3 ) !== round( $before['reserved'] - $released, 3 ) ) { return false; }
	}
	$delivered = self::issued_quantities_for_order( $s['order'] ); $total = $used = 0.0;
	foreach ( $s['order_fields']['_tkd_fo_order_items'] as $line ) { $sku = strtoupper( trim( $line['sku'] ) ); $qty = (float) $line['quantity']; $part = min( $qty, $delivered[$sku] ?? 0 ); $total += $qty; $used += $part; $delivered[$sku] = max( 0, ( $delivered[$sku] ?? 0 ) - $part ); }
	$complete = $total > 0 && $used + 0.0001 >= $total;
	if ( $used <= 0 || get_post_meta( $s['order'], '_tkd_fo_fulfillment_state', true ) !== ( $complete ? 'complete' : 'partial' ) || get_post_meta( $s['order'], '_tkd_fo_stock_state', true ) !== ( $complete ? 'shipped' : ( $after ? 'reserved' : 'none' ) ) || get_post_meta( $s['order'], '_tkd_status', true ) !== ( $complete ? 'shipped' : $plan['order_status_before'] ) || ( $complete && $after ) || get_post_meta( $s['delivery'], '_tkd_fo_delivery_previous_order_status', true ) !== $plan['order_status_before'] || get_post_meta( $s['order'], '_tkd_fo_status_before_partial_delivery', true ) !== ( $plan['status_before_partial'] ?: $plan['order_status_before'] ) ) { return false; }
	return true;
}

