private static function post_saved_for_handover_checked( $id, $office_revision ) {
	if ( ( $_SERVER['REQUEST_METHOD'] ?? '' ) !== 'POST' || ! current_user_can( 'manage_tkd_felicity' ) || ! is_numeric( $id ) || (int) $id <= 0 || (string) (int) $id !== (string) $id || ! is_string( $office_revision ) || ! self::warehouse_scanner_available() || self::$handover_post_scope !== null ) { return self::handover_post_error( 'Недостатньо прав, некоректний запит або складський захист недоступний.' ); }
