	$historical = self::historical_stock_guard( $id ); if ( is_wp_error( $historical ) ) { return $historical; }
	if ( ! hash_equals( TKD_Warehouse_Scanner::office_revision( $id ), $office_revision ) ) { return self::handover_post_error( 'Збережені документи змінилися. Оновіть сторінку перед проведенням.' ); }
	$s = self::handover_post_snapshot( $id ); $check = self::handover_post_valid( $s ); if ( is_wp_error( $check ) ) { return $check; }
	$check = TKD_Warehouse_Scanner::validate_office_change( $id, $s['delivery_fields']['items'], 'issued' ); if ( is_wp_error( $check ) ) { return $check; }
	$intent = get_post_meta( $id, self::HANDOVER_POST_META, true ); $status = get_post_meta( $id, '_tkd_fo_delivery_status', true ); $journal = get_post_meta( $id, '_tkd_fo_delivery_stock_journal', true );
	if ( $status === 'issued' ) {
		$processed = get_post_meta( $id, '_tkd_fo_delivery_stock_processed_at', true ); $date = is_string( $processed ) ? DateTimeImmutable::createFromFormat( '!Y-m-d H:i:s', $processed ) : false;
		// Current siblings were validated above; legitimate later partial shipments must not
		// invalidate this delivery's completed, immutable posting identity.
		$own_now = $s; unset( $own_now['siblings'] ); $own_before = is_array( $intent ) ? ( $intent['snapshot'] ?? null ) : null;
		if ( is_array( $own_before ) ) { unset( $own_before['siblings'] ); }
		if ( is_array( $intent ) && ( $intent['version'] ?? null ) === 1 && ( $intent['state'] ?? '' ) === 'committed' && ( $intent['notification'] ?? '' ) === 'completed' && $own_before === $own_now && is_array( $intent['plan'] ?? null ) && self::handover_post_journal_matches( $journal, $intent['plan']['journal'] ?? array() ) && $date && $date->format( 'Y-m-d H:i:s' ) === $processed && ( $intent['processed_at'] ?? null ) === $processed ) { return true; }
		return self::handover_post_error( 'Проведення історичне або не має завершеного intent цієї дії. Повторне списання заборонено.' );
	}
	if ( $status !== 'draft' || $intent !== '' || ( $journal !== '' && $journal !== array() ) || get_post_meta( $id, '_tkd_fo_delivery_stock_processed_at', true ) !== '' || get_post_meta( $id, '_tkd_fo_delivery_previous_order_status', true ) !== '' ) { return self::handover_post_error( 'Є журнал або незавершена/повторна спроба проведення. Потрібна окрема звірка; товар повторно не списано.' ); }
	$fiscal = self::fiscal_guard( $id ); if ( is_wp_error( $fiscal ) ) { return $fiscal; }
	$waybill = self::validate_waybill_before_issue( $s['order'] ); if ( is_wp_error( $waybill ) ) { return $waybill; }
	$allocation = TKD_FO_Scan_Reservation::allocate( $s ); if ( is_wp_error( $allocation ) ) { return $allocation; }
	$plan = self::handover_post_stock_plan( $s ); if ( is_wp_error( $plan ) ) { return $plan; }
	$intent = array( 'version' => 1, 'state' => 'pending', 'token' => bin2hex( random_bytes( 16 ) ), 'actor' => get_current_user_id(), 'created_at' => gmdate( 'Y-m-d H:i:s' ), 'office_revision' => $office_revision, 'snapshot' => $s, 'plan' => $plan );
	if ( ! add_post_meta( $id, self::HANDOVER_POST_META, wp_slash( $intent ), true ) ) { return self::handover_post_error( 'Не вдалося надійно зафіксувати початок проведення. Склад не змінено.' ); }
	wp_cache_delete( $id, 'post_meta' ); if ( get_post_meta( $id, self::HANDOVER_POST_META, true ) !== $intent ) { return self::handover_post_error( 'Початковий запис проведення не підтверджено. Повтор заблоковано.' ); }
	self::$handover_post_scope = array( 'delivery' => $id, 'token' => $intent['token'], 'order' => $s['order'], 'order_items' => $s['order_fields']['_tkd_fo_order_items'] );
	try {
		self::handover_post_fresh( $id );
		if ( self::handover_post_snapshot( $id ) !== $s || get_post_meta( $s['order'], '_tkd_fo_reserved_items', true ) !== $plan['reservation_raw'] || get_post_meta( $id, self::HANDOVER_POST_META, true ) !== $intent ) { return self::handover_post_error( 'Документи або резерв змінилися після intent. Склад не змінено; повтор заблоковано до звірки.' ); }
		$result = self::issue_delivery( $id, $s['delivery_fields']['items'] );
		if ( is_wp_error( $result ) ) { return self::handover_post_error( $result->get_error_message() . ' Проведення не завершено; повтор заблокований до звірки журналу.' ); }
		if ( ! self::handover_post_readback( $s, $plan ) ) { return self::handover_post_error( 'Проведення не підтверджено повністю. Intent збережено; повторне списання та ручне перезаписування заблоковані до звірки.' ); }
		if ( ! update_post_meta( $id, '_tkd_fo_delivery_status', 'issued', 'draft' ) ) { return self::handover_post_error( 'Склад міг бути списаний, але статус видаткової не підтверджено. Не повторюйте проведення.' ); }
		self::handover_post_fresh( $id );
		if ( get_post_meta( $id, '_tkd_fo_delivery_status', true ) !== 'issued' || get_post_meta( $id, self::HANDOVER_POST_META, true ) !== $intent || ! self::handover_post_readback( $s, $plan ) ) { return self::handover_post_error( 'Підсумок проведення змінився або не збережений. Потрібна окрема звірка.' ); }
		// Claim the normal committed notification before invoking listeners: no replay on crash/exception.
		$notifying = $intent; $notifying['notification'] = 'claimed';
		if ( ! update_post_meta( $id, self::HANDOVER_POST_META, wp_slash( $notifying ), $intent ) ) { return self::handover_post_error( 'Сповіщення складу не зафіксовано. Проведення потребує звірки.' ); }
		wp_cache_delete( $id, 'post_meta' ); if ( get_post_meta( $id, self::HANDOVER_POST_META, true ) !== $notifying ) { return self::handover_post_error( 'Сповіщення складу не підтверджене. Повтор заблоковано.' ); }
		do_action( 'tkd_fo_delivery_status_committed', $id, 'draft', 'issued', $s['delivery_fields']['items'] );
		if ( ! self::handover_post_readback( $s, $plan ) ) { return self::handover_post_error( 'Після сповіщення підсумок проведення не підтверджено.' ); }
		$done = $notifying; $done['state'] = 'committed'; $done['notification'] = 'completed'; $done['committed_at'] = gmdate( 'Y-m-d H:i:s' ); $done['processed_at'] = get_post_meta( $id, '_tkd_fo_delivery_stock_processed_at', true );
		if ( ! update_post_meta( $id, self::HANDOVER_POST_META, wp_slash( $done ), $notifying ) ) { return self::handover_post_error( 'Проведення виконане, але audit intent не завершений. Повтор заблоковано до звірки.' ); }
		wp_cache_delete( $id, 'post_meta' ); return get_post_meta( $id, self::HANDOVER_POST_META, true ) === $done ? true : self::handover_post_error( 'Завершений запис проведення не підтверджено.' );
	} catch ( Throwable $e ) { return self::handover_post_error( 'Невизначений результат проведення. Intent збережено, автоматичний повтор заборонено.' ); }
	finally { self::$handover_post_scope = null; }
}

private static function save_delivery_locked( $post_id, $post, $update ) {
	$historical = self::historical_stock_guard( $post_id ); if ( is_wp_error( $historical ) ) { TKD_FO_Inventory_Admin::set_notice( 'error', $historical->get_error_message() ); return; }
	$handover_intent = get_post_meta( $post_id, self::HANDOVER_POST_META, true );
	if ( $handover_intent !== '' && ( ! is_array( $handover_intent ) || ( $handover_intent['version'] ?? null ) !== 1 || ( $handover_intent['state'] ?? '' ) !== 'committed' ) ) {
		TKD_FO_Inventory_Admin::set_notice( 'error', 'Незавершена спроба проведення для передачі. Ручне збереження заблоковано, щоб не повторити списання; потрібна окрема звірка.' ); return;
	}
	$invoice_id = absint( get_post_meta( $post_id, '_tkd_fo_delivery_invoice_id', true ) );
	$previous_status = (string) get_post_meta( $post_id, '_tkd_fo_delivery_status', true );
	$previous_status = array_key_exists( $previous_status, self::status_labels() ) ? $previous_status : 'draft';
	$old_items  = get_post_meta( $post_id, '_tkd_fo_delivery_items', true );
	$old_items  = is_array( $old_items ) ? $old_items : array();
	$status     = isset( $_POST['tkd_fo_delivery_status'] ) && is_string( $_POST['tkd_fo_delivery_status'] ) ? sanitize_key( wp_unslash( $_POST['tkd_fo_delivery_status'] ) ) : $previous_status;
	$status     = array_key_exists( $status, self::status_labels() ) ? $status : $previous_status;
	$rework = ( $_POST['tkd_fo_delivery_command'] ?? '' ) === 'rework_delivery';
	$cancel = $rework || ( $_POST['tkd_fo_delivery_command'] ?? '' ) === 'cancel_delivery';
	if ( $rework && ( $_POST['tkd_fo_rework_on_site'] ?? '' ) !== '1' ) { TKD_FO_Inventory_Admin::set_notice( 'error', 'Підтвердьте, що всі товари ще на складі. Видаткову не змінено.' ); return; }
	if ( $cancel && ( $rework || self::was_posted( $post_id ) ) ) {
		$guard = self::rework_guard( $post_id );
		if ( is_wp_error( $guard ) ) { TKD_FO_Inventory_Admin::set_notice( 'error', $guard->get_error_message() ); return; }
	}
	if ( ! $cancel && self::was_posted( $post_id ) && $previous_status !== 'issued' ) { TKD_FO_Inventory_Admin::set_notice( 'error', 'Попереднє проведення збережено в історії. Для нової партії використайте «Переробити відвантаження» та нову видаткову, а не повторне проведення старої.' ); return; }
	if ( $cancel ) { $status = 'cancelled'; }
	if ( $status === 'cancelled' && $previous_status !== 'cancelled' && ! $cancel ) {
		self::status_audit( $post_id, 'blocked_implicit_cancel', $previous_status, $status );
		TKD_FO_Inventory_Admin::set_notice( 'warning', 'Видаткову не скасовано. Звичайне «Оновити» не скасовує документ; для цього є окрема кнопка «Скасувати видаткову».' ); return;
	}
	if ( $previous_status !== 'issued' && $status === 'issued' ) {
		$fiscal = self::fiscal_guard( $post_id ); if ( is_wp_error( $fiscal ) ) { TKD_FO_Inventory_Admin::set_notice( 'error', $fiscal->get_error_message() ); return; }
		// The fiscal gate verifies saved goods, never an unsaved form candidate.
		// Reject before number allocation or any broad form write; save a draft first.
		try {
			$candidate = self::sanitize_items( $invoice_id, $post_id, isset( $_POST['tkd_fo_delivery_items'] ) ? wp_unslash( $_POST['tkd_fo_delivery_items'] ) : array() );
			$unchanged = empty( $candidate['error'] ) && ! empty( $candidate['items'] ) && $candidate['items'] === $old_items;
		} catch ( Throwable $e ) { $unchanged = false; }
		if ( ! $unchanged ) { TKD_FO_Inventory_Admin::set_notice( 'error', 'Склад товарів відрізняється від збереженої видаткової. Спочатку збережіть чернетку, потім повторіть перевірку чека та проведення.' ); return; }
	}
	$resolved = self::delivery_items_for_display( $post_id );
	if ( $resolved['error'] && 'cancelled' !== $status ) {
		TKD_FO_Inventory_Admin::set_notice( 'error', $resolved['error'] );
		return;
	}
	$date       = isset( $_POST['tkd_fo_delivery_date'] ) ? sanitize_text_field( wp_unslash( $_POST['tkd_fo_delivery_date'] ) ) : wp_date( 'Y-m-d' );
	$number     = isset( $_POST['tkd_fo_delivery_number'] ) ? sanitize_text_field( wp_unslash( $_POST['tkd_fo_delivery_number'] ) ) : '';
	$seller_status = 'issued' === $previous_status ? 'issued' : ( 'cancelled' === $status ? 'cancelled' : 'draft' );
	$seller     = self::seller_key_for_delivery( $post_id, $seller_status );
	$error      = '';

	// A seller change can carry a draft number into another seller's sequence.
	// Repair only a saved draft's unchanged conflicting number, never an explicit
	// replacement supplied by the manager or any issued/cancelled document.
	$renumbered_from = '';
	if ( 'issued' !== $previous_status ) {
		$saved_number = trim( (string) get_post_meta( $post_id, '_tkd_fo_delivery_number', true ) );
		$duplicate = $number !== '' && self::number_exists( $seller, $number, $post_id );
		$repair_draft = 'draft' === $previous_status && 'draft' === $status && $duplicate && $number === $saved_number;
		if ( $duplicate && ! $repair_draft ) {
			TKD_FO_Inventory_Admin::set_notice( 'error', 'Цей номер уже зайнятий у продавця. Документ не змінено. Збережіть чернетку з її попереднім номером або залиште номер порожнім для автоматичної нумерації.' ); return;
		}
		if ( ! $number || $repair_draft ) {
			$renumbered_from = $repair_draft ? $number : '';
			$number = self::next_number( $seller, $date );
			if ( ! $number || self::number_exists( $seller, $number, $post_id ) ) {
				TKD_FO_Inventory_Admin::set_notice( 'error', 'Не вдалося призначити вільний номер. Документ не змінено; повторіть збереження чернетки.' ); return;
			}
		}
	}

	if ( 'issued' === $previous_status ) {
		$items = $old_items;
		$number = (string) get_post_meta( $post_id, '_tkd_fo_delivery_number', true );
		$date   = (string) get_post_meta( $post_id, '_tkd_fo_delivery_date', true );
		if ( 'cancelled' === $status ) {
			$stock_result = self::reverse_issued_delivery( $post_id );
			if ( is_wp_error( $stock_result ) ) {
				$error  = $error ? $error : $stock_result->get_error_message();
				$status = 'issued';
			}
		} elseif ( 'issued' !== $status ) {
			$error  = $error ? $error : 'Проведену видаткову можна лише скасувати з поверненням товару на склад.';
			$status = 'issued';
		}
	} elseif ( 'cancelled' === $status ) {
		// Cancelling an unissued note releases its allocation without remapping lines.
		$items = $old_items;
	} else {
		$raw_items = isset( $_POST['tkd_fo_delivery_items'] ) ? wp_unslash( $_POST['tkd_fo_delivery_items'] ) : array();
		$result    = self::sanitize_items( $invoice_id, $post_id, $raw_items );
		if ( ! empty( $result['source_mismatch'] ) ) {
			TKD_FO_Inventory_Admin::set_notice( 'error', $result['error'] );
			return;
		}
		$items     = $result['items'];
		if ( $result['error'] ) {
			$error  = $error ? $error : $result['error'];
			$status = 'draft';
		}
		if ( ! $items ) {
			$items  = $old_items;
			$error  = $error ? $error : 'Вкажіть кількість хоча б для однієї позиції.';
			$status = 'draft';
		}
		if ( self::warehouse_scanner_available() ) {
			$scanner_check = TKD_Warehouse_Scanner::validate_office_change( $post_id, $items, $status );
			if ( is_wp_error( $scanner_check ) ) {
				TKD_FO_Inventory_Admin::set_notice( 'error', $scanner_check->get_error_message() );
				return;
			}
		}
		if ( ! $error && 'issued' === $status ) {
			$stock_result = self::issue_delivery( $post_id, $items );
			if ( is_wp_error( $stock_result ) ) {
				$error  = $stock_result->get_error_message();
				$status = $previous_status;
			}
		}
	}

	if ( 'cancelled' === $previous_status && $error ) {
		// A failed reopen must leave the cancelled document's snapshot intact.
		TKD_FO_Inventory_Admin::set_notice( 'error', $error );
		return;
	}

	update_post_meta( $post_id, '_tkd_fo_delivery_number', $number );
	update_post_meta( $post_id, '_tkd_fo_delivery_date', $date );
	self::$cancel_scope = $cancel ? (int) $post_id : 0;
	try { update_post_meta( $post_id, '_tkd_fo_delivery_status', $status ); }
	finally { self::$cancel_scope = 0; }
	if ( get_post_meta( $post_id, '_tkd_fo_delivery_status', true ) !== $status ) {
		TKD_FO_Inventory_Admin::set_notice( 'error', 'Не підтверджено збереження статусу видаткової. Не повторюйте складську дію; перевірте журнал.' ); return;
	}
	if ( ! $error && $previous_status !== $status ) { self::status_audit( $post_id, $cancel ? 'manager_cancel' : 'manager_save', $previous_status, $status ); }
	update_post_meta( $post_id, '_tkd_fo_delivery_seller_key', $seller );
	update_post_meta( $post_id, '_tkd_fo_delivery_items', $items );
	foreach ( array( 'place', 'receiver', 'payer', 'contract', 'application' ) as $field ) {
		if ( 'issued' === $previous_status ) {
			continue;
		}
		$value = isset( $_POST[ 'tkd_fo_delivery_' . $field ] ) ? sanitize_text_field( wp_unslash( $_POST[ 'tkd_fo_delivery_' . $field ] ) ) : '';
		update_post_meta( $post_id, '_tkd_fo_delivery_' . $field, $value );
	}

	if ( ! $error && $status === 'cancelled' && is_callable( array( 'TKD_Warehouse_Scanner', 'archive_cancelled_task' ) ) ) {
		$task_archive = TKD_Warehouse_Scanner::archive_cancelled_task( $post_id );
		if ( is_wp_error( $task_archive ) ) { TKD_FO_Inventory_Admin::set_notice( 'error', $task_archive->get_error_message() ); return; }
	}
	if ( ! $error && $previous_status !== $status && ( 'issued' === $status || ( 'issued' === $previous_status && 'cancelled' === $status ) ) && function_exists( 'do_action' ) ) {
		// Notification only: existing financial/stock processing and final metadata are already committed.
		do_action( 'tkd_fo_delivery_status_committed', $post_id, $previous_status, $status, $items );
	}
	if ( $error ) {
		TKD_FO_Inventory_Admin::set_notice( 'error', $error );
	} else {
		$message = 'issued' === $status ? 'Видаткову проведено: товар списано зі складу по фактичних позиціях.' : ( 'cancelled' === $status && 'issued' === $previous_status ? 'Видаткову скасовано: товар повернуто на склад, резерв відновлено.' : 'Видаткову накладну збережено.' );
		if ( $renumbered_from ) { $message .= ' Номер ' . $renumbered_from . ' уже зайнятий у цього продавця; чернетці присвоєно № ' . $number . '.'; }
		TKD_FO_Inventory_Admin::set_notice( 'success', $message );
	}

	self::$saving = true;
	wp_update_post(
		array(
			'ID'          => $post_id,
			'post_title'  => $number ? 'Видаткова накладна ' . $number : 'Чернетка видаткової #' . $post_id,
			'post_status' => 'publish',
		)
	);
	self::$saving = false;
	if ( ! $error && isset( $_POST['post_ID'] ) && absint( $_POST['post_ID'] ) === (int) $post_id ) {
		$order_id = absint( get_post_meta( $post_id, '_tkd_fo_delivery_order_id', true ) );
		if ( ! $order_id && $invoice_id ) {
			$order_id = absint( get_post_meta( $invoice_id, '_tkd_fo_order_id', true ) );
		}
		TKD_FO_Orders::claim_responsibility( $order_id, 'Збережено видаткову № ' . $number );
	}
}

private static function issue_delivery( $delivery_id, $items ) {
	$historical = self::historical_stock_guard( $delivery_id ); if ( is_wp_error( $historical ) ) { return $historical; }
	$saved_items = get_post_meta( $delivery_id, '_tkd_fo_delivery_items', true );
	if ( ! is_array( $saved_items ) || ! $saved_items || $items !== $saved_items ) { return self::handover_post_error( 'Незбережені зміни товарів не можна провести за перевіркою чека для іншого складу. Спочатку збережіть чернетку.' ); }
	$fiscal = self::fiscal_guard( $delivery_id ); if ( is_wp_error( $fiscal ) ) { return $fiscal; }
	$handover_intent = get_post_meta( $delivery_id, self::HANDOVER_POST_META, true );
	if ( $handover_intent !== '' && ( ! is_array( $handover_intent ) || ( $handover_intent['state'] ?? '' ) !== 'pending' || ( self::$handover_post_scope['delivery'] ?? null ) !== (int) $delivery_id || ( self::$handover_post_scope['token'] ?? null ) !== ( $handover_intent['token'] ?? null ) ) ) { return self::handover_post_error( 'Повторне проведення видаткової з audit intent заборонено.' ); }
	$existing = get_post_meta( $delivery_id, '_tkd_fo_delivery_stock_journal', true );
	if ( is_array( $existing ) && $existing ) {
		return true;
	}

	$order_id  = absint( get_post_meta( $delivery_id, '_tkd_fo_delivery_order_id', true ) );
	$invoice_id = absint( get_post_meta( $delivery_id, '_tkd_fo_delivery_invoice_id', true ) );
	$number    = trim( (string) get_post_meta( $delivery_id, '_tkd_fo_delivery_number', true ) );
	$waybill_guard = self::validate_waybill_before_issue( $order_id );
	if ( is_wp_error( $waybill_guard ) ) {
		return $waybill_guard;
	}
	$reserved  = self::order_reservation_map( $order_id );
	$plan      = array();

	foreach ( $items as $line ) {
		$sku = isset( $line['sku'] ) ? trim( (string) $line['sku'] ) : '';
		$qty = TKD_FO_DB::decimal( isset( $line['quantity'] ) ? $line['quantity'] : 0, 3 );
		$item = $sku ? TKD_FO_DB::get_item_by_sku( $sku ) : null;
		if ( ! $item || $qty <= 0 ) {
			return new WP_Error( 'tkd_fo_delivery_stock_match', 'Не знайдено складську позицію для «' . ( isset( $line['name'] ) ? $line['name'] : $sku ) . '».' );
		}
		$item_id = (int) $item->id;
		if ( ! isset( $plan[ $item_id ] ) ) {
			$plan[ $item_id ] = array( 'item_id' => $item_id, 'sku' => $item->sku, 'quantity' => 0, 'reserved_released' => 0 );
		}
		$plan[ $item_id ]['quantity'] = round( $plan[ $item_id ]['quantity'] + $qty, 3 );
	}

	foreach ( $plan as &$entry ) {
		$item = TKD_FO_DB::get_item( $entry['item_id'] );
		$entry['reserved_released'] = min( $entry['quantity'], isset( $reserved[ $entry['item_id'] ] ) ? $reserved[ $entry['item_id'] ] : 0 );
		if ( ! $item || (float) $item->on_hand + 0.0001 < $entry['quantity'] ) {
			return new WP_Error( 'tkd_fo_delivery_shortage', 'Не вистачає фізичного залишку для ' . $entry['sku'] . '. Спочатку проведіть надходження на склад.' );
		}
		if ( (float) $item->reserved + 0.0001 < $entry['reserved_released'] ) {
			return new WP_Error( 'tkd_fo_delivery_reservation_mismatch', 'Резерв для ' . $entry['sku'] . ' не збігається зі складом. Перевірте замовлення перед відвантаженням.' );
		}
	}
	unset( $entry );

	$processed = array();
	foreach ( $plan as $entry ) {
		$result = TKD_FO_DB::change_stock(
			$entry['item_id'],
			array( 'on_hand' => -$entry['quantity'], 'reserved' => -$entry['reserved_released'] ),
			array(
				'type'       => 'delivery_ship',
				'order_id'   => $order_id,
				'invoice_id' => $invoice_id,
				'note'       => 'Видаткова № ' . $number . ' (часткове або повне відвантаження)',
			)
		);
		if ( is_wp_error( $result ) ) {
			self::rollback_stock_changes( $processed, $order_id, $invoice_id, $number );
			return $result;
		}
		$processed[] = $entry;
	}

	self::reduce_order_reservation( $order_id, $processed );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_stock_journal', array_values( $processed ) );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_stock_processed_at', current_time( 'mysql' ) );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_previous_order_status', get_post_meta( $order_id, '_tkd_status', true ) );
	if ( ! get_post_meta( $order_id, '_tkd_fo_status_before_partial_delivery', true ) ) {
		update_post_meta( $order_id, '_tkd_fo_status_before_partial_delivery', get_post_meta( $order_id, '_tkd_status', true ) );
	}
	self::refresh_order_fulfillment( $order_id, $invoice_id );
	return true;
}

public static function validate_waybill_before_issue( $order_id ) {
	$order_id = absint( $order_id );
	if ( ! $order_id ) {
		return new WP_Error( 'tkd_fo_delivery_order_missing', 'Видаткову не прив’язано до замовлення.' );
	}
	$delivery_method = sanitize_key( (string) get_post_meta( $order_id, '_tkd_np_delivery_method', true ) );
	if ( 'pickup' === $delivery_method ) {
		return true;
	}
	$waybill = trim( (string) get_post_meta( $order_id, '_tkd_np_document_number', true ) );
	if ( ! preg_match( '/^\d{12,20}$/D', $waybill ) ) {
		return new WP_Error( 'tkd_fo_delivery_waybill_required', 'Перед проведенням видаткової внесіть і збережіть ЕН Нової пошти (12–20 цифр) у картці замовлення.' );
	}
	return true;
}

public static function create_from_invoice() {
	if ( ! current_user_can( 'manage_tkd_felicity' ) ) {
		wp_die( 'Недостатньо прав.' );
	}
	$invoice_id = isset( $_GET['invoice_id'] ) ? absint( $_GET['invoice_id'] ) : 0;
	check_admin_referer( 'tkd_fo_create_delivery_' . $invoice_id );
	if ( ! $invoice_id || 'tkd_invoice' !== get_post_type( $invoice_id ) ) {
		wp_die( 'Рахунок не знайдено.' );
	}
	$invoice_items = get_post_meta( $invoice_id, '_tkd_fo_invoice_items', true );
	$allocated     = self::allocated_quantities( $invoice_id );
	$items         = array();
	foreach ( is_array( $invoice_items ) ? $invoice_items : array() as $index => $source ) {
		$remaining = max( 0, (float) $source['quantity'] - ( isset( $allocated[ $index ] ) ? (float) $allocated[ $index ] : 0 ) );
		if ( $remaining <= 0 ) {
			continue;
		}
		$items[] = array(
			'source_index' => $index,
			'sku'          => isset( $source['sku'] ) ? $source['sku'] : '',
			'name'         => isset( $source['name'] ) ? $source['name'] : '',
			'unit'         => isset( $source['unit'] ) ? $source['unit'] : 'шт',
			'quantity'     => $remaining,
			'unit_price'   => isset( $source['unit_price'] ) ? (float) $source['unit_price'] : 0,
		);
	}
	if ( ! $items ) {
		TKD_FO_Inventory_Admin::set_notice( 'error', 'Усі позиції рахунку вже розподілені між видатковими накладними.' );
		wp_safe_redirect( get_edit_post_link( $invoice_id, '' ) );
		exit;
	}

	$date        = wp_date( 'Y-m-d' );
	$seller      = get_post_meta( $invoice_id, '_tkd_fo_seller_key', true );
	$number      = self::next_number( $seller, $date );
	$order_id    = absint( get_post_meta( $invoice_id, '_tkd_fo_order_id', true ) );
	$buyer_name  = get_post_meta( $invoice_id, '_tkd_fo_buyer_name', true );
	$receiver    = get_post_meta( $invoice_id, '_tkd_fo_receiver', true );
	$payer       = get_post_meta( $invoice_id, '_tkd_fo_payer', true );
	$application = get_post_meta( $invoice_id, '_tkd_fo_application', true );
	if ( ! $application && $order_id ) {
		$application = get_post_meta( $order_id, '_tkd_order_number', true );
	}

	$delivery_id = wp_insert_post( array( 'post_type' => 'tkd_delivery', 'post_status' => 'publish', 'post_title' => 'Видаткова накладна ' . $number ) );
	if ( is_wp_error( $delivery_id ) || ! $delivery_id ) {
		wp_die( 'Не вдалося створити видаткову накладну.' );
	}
	update_post_meta( $delivery_id, '_tkd_fo_delivery_invoice_id', $invoice_id );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_order_id', $order_id );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_seller_key', $seller );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_number', $number );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_date', $date );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_place', 'м. Дніпро' );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_status', 'draft' );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_receiver', $receiver ? $receiver : $buyer_name );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_payer', $payer ? $payer : $buyer_name );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_contract', get_post_meta( $invoice_id, '_tkd_fo_contract', true ) );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_application', $application );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_items', $items );
	TKD_FO_Inventory_Admin::set_notice( 'success', 'Створено окрему видаткову накладну. Перевірте фактичну кількість і дату.' );
	TKD_FO_Orders::claim_responsibility( $order_id, 'Створено видаткову № ' . $number );
	wp_safe_redirect( get_edit_post_link( $delivery_id, '' ) );
	exit;
}

private static function allocated_quantities( $invoice_id, $exclude_delivery_id = 0 ) {
	$allocated = array();
	if ( ! $invoice_id ) {
		return $allocated;
	}
	$deliveries = get_posts(
		array(
			'post_type'      => 'tkd_delivery',
			'post_status'    => 'any',
			'posts_per_page' => -1,
			'post__not_in'   => $exclude_delivery_id ? array( absint( $exclude_delivery_id ) ) : array(),
			'meta_key'       => '_tkd_fo_delivery_invoice_id',
			'meta_value'     => $invoice_id,
			'fields'         => 'ids',
		)
	);
	foreach ( $deliveries as $delivery_id ) {
		if ( 'cancelled' === get_post_meta( $delivery_id, '_tkd_fo_delivery_status', true ) ) {
			continue;
		}
		$items = get_post_meta( $delivery_id, '_tkd_fo_delivery_items', true );
		foreach ( is_array( $items ) ? $items : array() as $item ) {
			$index = isset( $item['source_index'] ) ? (int) $item['source_index'] : -1;
			if ( $index < 0 ) {
				continue;
			}
			$allocated[ $index ] = isset( $allocated[ $index ] ) ? $allocated[ $index ] + (float) $item['quantity'] : (float) $item['quantity'];
		}
	}
	return $allocated;
}

private static function allowed( $id, $type ) {
	if ( self::id( $id ) ) { wp_cache_delete( $id, 'posts' ); }
	return self::id( $id ) && current_user_can( 'manage_tkd_felicity' ) && current_user_can( 'edit_post', $id ) && get_post_type( $id ) === $type
		&& in_array( get_post_status( $id ), array( 'publish', 'draft', 'pending', 'private', 'future' ), true );
}

private static function minor( $v ) {
	if ( ! is_numeric( $v ) || ! is_finite( (float) $v ) || (float) $v < 0 || (float) $v > 1000000000 || abs( (float) $v - round( (float) $v, 2 ) ) > 0.000001 ) { return null; }
	return (int) round( (float) $v * 100 );
}

private static function invoice_consistent( $r ) {
	$sum = 0;
	foreach ( $r['_tkd_fo_invoice_items'] as $line ) {
