private static function physical_stock_blockers( $items, $status ) {
	// Posted deliveries already consumed their stock: never demand it a second time.
	if ( $status !== 'draft' ) { return array(); }
	if ( ! is_array( $items ) || ! $items ) { return array( 'Немає збережених товарів для перевірки фізичного залишку.' ); }
	if ( ! is_callable( array( 'TKD_FO_DB', 'get_item_by_sku' ) ) ) { return array( 'Перевірка фізичного залишку недоступна. Проведення не запускалося.' ); }
	$needed = array();
	foreach ( $items as $line ) {
		if ( ! is_array( $line ) || ! is_string( $line['sku'] ?? null ) || trim( $line['sku'] ) === '' || ! is_numeric( $line['quantity'] ?? null ) || ! is_finite( (float) $line['quantity'] ) || (float) $line['quantity'] <= 0 || (float) $line['quantity'] > 1000000000 || round( (float) $line['quantity'], 3 ) !== (float) $line['quantity'] ) { return array( 'Артикул або кількість видаткової потребують звірки перед перевіркою складу.' ); }
		$sku = $line['sku']; $needed[$sku] = round( ( $needed[$sku] ?? 0 ) + (float) $line['quantity'], 3 );
	}
	$blockers = array();
	foreach ( $needed as $sku => $qty ) {
		try { $item = TKD_FO_DB::get_item_by_sku( $sku ); }
		catch ( Throwable $error ) { return array( 'Не вдалося перевірити фізичний залишок. Проведення не запускалося.' ); }
		if ( ! is_object( $item ) || empty( $item->id ) || (string) ( $item->sku ?? '' ) !== (string) $sku || ! is_numeric( $item->on_hand ?? null ) || ! is_finite( (float) $item->on_hand ) || (float) $item->on_hand < 0 ) { $blockers[] = $sku . ': фізичний залишок не підтверджено; потрібна звірка складу.'; continue; }
		if ( (float) $item->on_hand < $qty ) {
			$format = static function( $n ) { return rtrim( rtrim( number_format( $n, 3, ',', ' ' ), '0' ), ',' ); };
			$blockers[] = $sku . ': для видаткової потрібно ' . $format( $qty ) . ', фізично на складі ' . $format( (float) $item->on_hand ) . '. Резерв під поставку не є фізичним залишком. Видаткова залишається чернеткою до фактичного надходження товару.';
		}
	}
	return $blockers;
}

